import sys

ONES = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
        "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen",
        "eighteen", "nineteen"]
TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
SCALES = ["", " thousand", " million", " billion", " trillion"]

def below_thousand(n):
    words = ""
    if n >= 100:
        words += ONES[n // 100] + " hundred "
        n %= 100
    if n >= 20:
        words += TENS[n // 10] + " "
        n %= 10
    words += ONES[n]
    return words.strip()


def to_words(n):
    if n == 0:
        return "zero"
    words = ""
    scale = 0
    while n > 0:
        group = n % 1000
        words_group = below_thousand(group)
        if words_group:
            words = words_group + SCALES[scale] + " " + words
        n //= 1000
        scale += 1
    return words.strip()


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        sign = 1
        if line.startswith("-"):
            sign = -1
            num_str = line[1:]
        else:
            num_str = line
        n = int(num_str) * sign
        if n == 0:
            print("zero")
        else:
            words = to_words(abs(n))
            if sign == -1:
                words = "minus " + words
            print(words)


if __name__ == "__main__":
    main()
